// Biblioteca GMO de plantillas de avisos operativos (dbo.operationalNoticeTemplates).
// Global: no companyId. Any staff reads it; only the SmartLoans admin writes (backend guard).
// Generated by posgmo-factory (PRD prd_operationalNoticeTemplate.json), fixed by hand.
import { API_BASE_URL } from '../utils/appEnv';
import type { NoticeType } from './operationalNoticeApi';

const LOG = '[operationalNoticeTemplateApi]';

export interface OperationalNoticeTemplate {
  operationalNoticeTemplateId: number;
  templateKey: string;
  name: string;
  description: string;
  icon: string;
  noticeType: NoticeType;
  defaultTitle: string;
  defaultMessage: string;
  /** Placeholders the POS asks for, in order (e.g. ['motivo', 'fecha_reapertura', 'horario']). */
  variables: string[];
  blocksReservations: boolean;
  sortOrder: number | null;
  status: 'activo' | 'retirado';
}

export type OperationalNoticeTemplateInput = Omit<OperationalNoticeTemplate, 'operationalNoticeTemplateId' | 'status'>;

interface Row extends Omit<OperationalNoticeTemplate, 'variables' | 'blocksReservations'> {
  variables: string;
  blocksReservations: number;
}

async function post<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.error || data?.status === 'error') {
    const message = data?.message || data?.error || data?.detail || `HTTP ${res.status}`;
    console.error(LOG, path, message);
    throw new Error(typeof message === 'string' ? message : 'Error');
  }
  return data as T;
}

const toInput = (t: Partial<OperationalNoticeTemplateInput>) => ({
  ...t,
  variables: t.variables?.join(','),
  blocksReservations: t.blocksReservations === undefined ? undefined : (t.blocksReservations ? 1 : 0),
});

/** status 'activo' (library) by default; 'all' includes retired ones (platform admin). */
export async function getAllOperationalNoticeTemplates(status: 'activo' | 'all' = 'activo'): Promise<OperationalNoticeTemplate[]> {
  const data = await post<{ operationalNoticeTemplates?: Row[] }>(
    '/all_operationalNoticeTemplates', { operationalNoticeTemplates: [{ status }] });
  return (data.operationalNoticeTemplates ?? []).map(r => ({
    ...r,
    variables: (r.variables || '').split(',').map(v => v.trim()).filter(Boolean),
    blocksReservations: Number(r.blocksReservations) === 1,
  }));
}

export async function createOperationalNoticeTemplate(input: OperationalNoticeTemplateInput): Promise<void> {
  await post('/operationalNoticeTemplates', { operationalNoticeTemplates: [{ action: 1, ...toInput(input) }] });
}

export async function updateOperationalNoticeTemplate(
  id: number, input: Omit<OperationalNoticeTemplateInput, 'templateKey'>,
): Promise<void> {
  await post('/operationalNoticeTemplates', {
    operationalNoticeTemplates: [{ action: 2, operationalNoticeTemplateId: id, ...toInput(input) }],
  });
}

export async function retireOperationalNoticeTemplate(id: number): Promise<void> {
  await post('/operationalNoticeTemplates', { operationalNoticeTemplates: [{ action: 3, operationalNoticeTemplateId: id }] });
}
